package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.*;
public final class ContextSignedWitnessBoundaryRunner {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 static Snapshot bind(boolean x,String text)throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);require(m.compile(text,null,false),"actual signed inventory compilation");ContextProductionInventory v=ContextProductionInventory.inspect(m,UUID.randomUUID(),1,x,Collections.emptyList(),1000);ContextProductionNativeBinding.Result r=ContextProductionNativeBinding.bind(m,v,WORK,500000);require(r.bound,r.reason);return r.snapshot;}
 public static void main(String[] args){try{
  Snapshot x=bind(true,"!$u seed(u,1)&&~blocked(u,1); !~raw(2);");ContextWitnessResultTransport.Result exported=ContextWitnessResultTransport.primarySeeds(x,WORK);require(exported.exported&&exported.packet.items.size()==3,"signed primary materialization is available independently of row eligibility");
  Item seed=exported.packet.items.stream().filter(i->i.atom.predicate.equals("seed")).findFirst().get(),negative=exported.packet.items.stream().filter(i->i.atom.predicate.equals("blocked")).findFirst().get(),raw=exported.packet.items.stream().filter(i->i.atom.predicate.equals("raw")).findFirst().get();
  require(seed.atom.positive&&!negative.atom.positive&&!raw.atom.positive,"materialization preserves both witness and scalar literal signs");require(seed.atom.arguments.get(0).origin.equals(negative.atom.arguments.get(0).origin)&&seed.atom.arguments.get(0).origin.binder==0,"same bundle binder retains same Source-owned Origin across signs");require(raw.atom.arguments.get(0).origin==null,"ordinary negative scalar is not an Origin");for(Item item:exported.packet.items)require(item.proofs.size()==1&&item.proofs.get(0).depth==0&&item.proofs.get(0).sources.size()==1&&item.proofs.get(0).sources.iterator().next().localX,"every materialized item retains exact original depth0 Source");
  ContextUniversalNativeRows.Result rows=ContextUniversalNativeRows.inspect(x,null,64,WORK);require(rows.classified&&!rows.withinShape&&rows.rows.size()==2&&rows.sources.size()==2,"whole signed existential remains explicitly unsupported, no partial row split");require(rows.rows.stream().anyMatch(r->r.parts.stream().anyMatch(p->p.role==ContextUniversalNativeRows.Role.UNSUPPORTED&&p.reason.contains("Signed existential"))),"existential sign restriction belongs to whole-row language classification");require(rows.rows.stream().anyMatch(r->r.parts.stream().anyMatch(p->p.role==ContextUniversalNativeRows.Role.CONSTRAINT)),"negative scalar row still classified as a constraint");
  Snapshot positive=bind(false,"!$v other(v,1);");PrivatePool accepted=ContextWitnessResultTransport.privatePoolSigned(exported.packet,x,positive,WORK);require(accepted.local.items.stream().anyMatch(i->i.atom.predicate.equals("blocked")&&!i.atom.positive),"existing signed-common mode retains negative common atom");Item other=accepted.local.items.stream().filter(i->i.atom.predicate.equals("other")).findFirst().get();require(other.atom.arguments.get(0).origin.binder==0&&!other.atom.arguments.get(0).origin.equals(seed.atom.arguments.get(0).origin),"different Source/binder0 origins stay distinct in existing private carrier");
  Snapshot signed=bind(false,"!$u seed(u,1)&&~blocked(u,1);");boolean rejected=false;try{ContextWitnessResultTransport.privatePoolSigned(exported.packet,x,signed,WORK);}catch(IllegalStateException expected){rejected=expected.getMessage().contains("Positive private witness bundle required");}require(rejected,"signed-common mode does not silently enable signed private bundle");
  ContextUniversalFrozenBranch.Limits limits=new ContextUniversalFrozenBranch.Limits(16,16,16,512,256,WORK,65536,65536);ContextUniversalInitialEntry.Result stopped=ContextUniversalInitialEntry.assemble(x,Collections.singletonList(positive),limits,4096);require(stopped.status==ContextUniversalInitialEntry.Status.INCOMPLETE&&stopped.phase.equals("whole-rows")&&stopped.entry==null&&stopped.refutations.isEmpty(),"initial native pipeline stops before materialization/inference and exposes no prefix");ContextWitnessResultTransport.Result bounded=ContextWitnessResultTransport.primarySeeds(x,1);require(!bounded.exported&&bounded.packet==null,"bounded primary materialization exposes no partial signed packet");
  System.out.println("SIGNED_WITNESS_BOUNDARIES materializationPreservesSigns=true exactSourceBinder=true classifierDistinct=true oldPrivateGate=true noInitialPrefix=true");System.out.println("CONTEXT_SIGNED_WITNESS_BOUNDARY_PASS checks="+checks);System.exit(0);
 }catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
